  "glowstick-scatter": { desc: "glowsticks in mixed neons, stuck in the ground and strewn about", pieces: [["glowsticks-stuck", 0, 0, undefined, "pink"], ["glowsticks-strewn", .7, .3, undefined, "cyan"], ["glowstick-crushed", -.6, .4, undefined, "acid"], ["glowsticks-stuck", -.4, -.5, "left", "lemon"], ["glowstick-crushed", .5, -.4, undefined, "violet"]] },
