export const PARTY_CLUSTERS = Object.entries(CLUSTERS).map(([id, d]) => ({ id, size: "party", ...d, pieces: d.pieces.map(([p, x, z, f, neon]) => [`party:${p}${neon && PARTY_BY_ID[p]?.light === "neon" ? "@" + neon : ""}`, x, z, f]) })); // (a warm piece carries no neon)
export const PARTY_CLUSTER_BY_ID = Object.fromEntries(PARTY_CLUSTERS.map(d => [d.id, d]));

// A sample patch of party ground, for the lab and previews: clusters and loose litter and lights scattered over a w × h
// pixel patch, as the prototype might. Returns [{ ref, x, y, depth }] (each piece's origin on the patch, in pixels; depth for
// sorting); compose with scenePiece(ref) and draw decals first. Clusters come from layout(id, { mirror }) (scenePlacements).
export function partyPatch(seed, layout, { w = 420, h = 250, clusters = 5, loose = 46 } = {}) {
  let t = seed * 9301 + 49297; const r = () => (t = (t * 9301 + 49297) % 233280) / 233280;
  const out = [], spots = [[.21, .28], [.71, .24], [.48, .6], [.17, .76], [.81, .76]].slice(0, clusters);
  spots.forEach(([fx, fy], i) => { const id = PARTY_CLUSTERS[(i * 3 + seed) % PARTY_CLUSTERS.length].id; for (const p of layout(id, { mirror: r() < .5 })) out.push({ ref: p.ref, x: fx * w + p.ox, y: fy * h + p.oy, flip: p.flip, depth: fy * h + p.oy }); });
  const pool = PARTY_OBJECTS.filter(d => d.cls === "litter" || d.cls === "small");
  for (let i = 0; i < loose; i++) { const d = pool[Math.floor(r() * pool.length)], n = PARTY_LIGHT_NEONS[Math.floor(r() * PARTY_LIGHT_NEONS.length)], x = 10 + r() * (w - 20), y = 14 + r() * (h - 20); out.push({ ref: `party:${d.id}${d.light === "neon" ? "@" + n : ""}`, x, y, flip: r() < .5, depth: y }); }
  return out;
}
